def _parse_timestamp(value: str | None, field: str) -> datetime | None:
    """Parse an ISO-8601 UTC timestamp ending in Z; absent means no boundary."""
    if value is None:
        return None
    if not isinstance(value, str) or not value.endswith("Z"):
        raise ValidationError(f"{field} must be an ISO-8601 UTC timestamp ending in Z")
    try:
        parsed = datetime.fromisoformat(value[:-1] + "+00:00")
    except ValueError as error:
        raise ValidationError(f"{field} must be an ISO-8601 UTC timestamp ending in Z") from error
    return parsed


def _parse_stored_time(value: str) -> datetime:
    """Parse a timestamp the service itself stored (always a UTC value ending in Z)."""
    return datetime.fromisoformat(value[:-1] + "+00:00")


def _iso_utc(epoch_seconds: float) -> str:
    """Render epoch seconds as an ISO-8601 UTC timestamp string ending in Z."""
    return datetime.fromtimestamp(epoch_seconds, timezone.utc).isoformat().replace("+00:00", "Z")


def _bucket_start(occurred_at: datetime, bucket: str) -> datetime:
    """Floor a UTC timestamp to the start of its fixed time bucket.

    ``hour`` aligns to the UTC hour and ``day`` to UTC midnight; both drop the
    finer fields rather than shifting any instant, so UTC alignment never
    depends on the caller's locale.
    """
    if bucket == USAGE_BUCKET_HOUR:
        return occurred_at.replace(minute=0, second=0, microsecond=0)
    return occurred_at.replace(hour=0, minute=0, second=0, microsecond=0)


def _format_bucket_start(start: datetime) -> str:
    """Render a bucket start as the stored ISO-8601 UTC form ending in Z."""
    return start.isoformat().replace("+00:00", "Z")


def _prometheus_label(value: str) -> str:
    """Escape a label value for the Prometheus text exposition format."""
    return value.replace("\\", "\\\\").replace("\n", "\\n").replace('"', '\\"')


def _json_type(value: Any) -> str:
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "boolean"
    if isinstance(value, (int, float)):
        return "number"
    if isinstance(value, str):
        return "string"
    return "other"


def _evaluate_condition(node: Node, input_data: Any) -> bool:
    current = input_data
    for segment in node.path.split("."):
        if not isinstance(current, dict) or segment not in current:
            return False
        current = current[segment]
    return _json_type(current) == _json_type(node.equals) and current == node.equals


